/**
 * Client plugin:
 *   - registers the approval mode chip in the composer tool row
 *   - registers an "Approval Modes" page in the Web UI settings sidebar
 *
 * Both registrations bind against the plugin entry's volatile Config: the
 * chip routes through `/approval-mode` slash command (per-session mode switch),
 * while the settings page binds the user-editable section (10 of the 18
 * Config fields — the rest stay deployer-only). Settings writes flow through
 * the configForms RPC back to the Host, whose runtime folds them into the
 * entry's profile user layer and updates the live volatile references.
 */
// DSH 0.1.2-alpha.3 把 dsh-client-runtime 重命名为 dsh-client-modules，
// ClientContext 收敛到 cordis 的 Context、SessionId 拆到 dsh-session/types。
// 这里按新版路径取，避免依赖废弃包。
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
// Type-only: pulls the ui-renderer Context merge (ctx.slots). `slots` is now
// declared on Context by dsh-client-ui-renderer, not the slots core.
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
// Type-only: pulls the ui-session merge (SessionStandardProps.sessionId:
// SessionId). Without this, slots.register's inject parameter falls back to
// `string`, and our branded SessionId handler fails to type-check.
import type {} from '@deepseek-ai/dsh-client-ui-session/client'
// Type-only: pulls the ui-conversation SlotMap merge (the composer dock seat).
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
// Type-only: pulls the locale plugin's Context merge (ctx.locale).
import type {} from '@deepseek-ai/dsh-client-locale/client'
// Type-only: pulls the api-remotes merge for ctx.remote.commands.
import type {} from '@deepseek-ai/dsh-api-remotes/client'
// Type-only: pulls the ui-settings SlotMap merge (the settings.section seat).
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'
import { ApprovalModeChip, type ApprovalModeChipInjected } from './ApprovalModeChip'
import { ApprovalModeSettings, type ApprovalModeSettingsInjected } from './ApprovalModeSettings'
import { SmartModelDirectoryController } from './model-directory'
import { parseApprovalMode } from './mode-text'
import type { ApprovalMode, Config } from '../index'
import { en, zh, enPage, zhPage, type ApprovalKey, type ApprovalPageKey } from './locales'

export type { ApprovalKey, ApprovalPageKey } from './locales'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** The approval mode chip's copy. */
    'dsh-user-approval-mode': ApprovalKey
    /** The approval mode settings page copy (sidebar label, sub-section headers, field labels, controls). */
    'dsh-user-approval-mode-page': ApprovalPageKey
  }
}

/** Dictionary namespace owned by the chip. `dsh-user-approval-mode*` prefix
 *  avoids colliding with the official `@deepseek-ai/dsh-user-approval` package
 *  (which also registers a locale named `approval`). */
const NS = 'dsh-user-approval-mode'
/** Dictionary namespace owned by the settings page. */
const NS_PAGE = 'dsh-user-approval-mode-page'
/** Settings slot id (page key in the settings sidebar; distinct from the profile entry id). */
const SETTINGS_ID = 'approval-mode'
/** Profile entry id = settings namespace key (`cordis.patch.yml` `id:`). */
const ENTRY_ID = 'dsh-user-approval-mode'
/** Settings slot order: bottom of the sidebar, after the Plugins section. */
const SETTINGS_ORDER = 1100

/** Required services: slot registry, commands Remote, locale registry, configuration forms. */
export const inject = ['slots', 'remote', 'remote.commands', 'remote.session', 'locale', 'configForms']

/**
 * Per-session mode cache for the chip — a first-paint hint, not the source of
 * truth. Survives chip unmount/remount on session switches so a revisit paints
 * the last known mode with no 'off' flicker, while the mount effect revalidates
 * against the server and corrects the display. Written by a successful chip
 * switch and by a refresh that wins its race against a switch. The Map lives on
 * the module scope, so a DSH restart (browser reload / HMR) drops it along with
 * everything else — no explicit cleanup needed. Bounded by the user's active
 * session count.
 */
const sessionModeCache = new Map<SessionId, ApprovalMode>()

/**
 * Client plugin body: register both the composer chip and the settings page.
 * @param ctx - client root context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-user-approval: chip dictionary')
  ctx.effect(() => ctx.locale.register(NS_PAGE, { zh: zhPage, en: enPage }), 'dsh-user-approval: settings page dictionary')

  // Bound translate function for the settings page namespace. Stable per
  // namespace, reads the active locale at call time, so the slot label thunk
  // below picks up locale changes on each render without re-registration.
  const tPage = ctx.locale.bind(NS_PAGE)

  // ── Composer chip (per-session mode switch via /approval-mode command) ──
  ctx.slots.inject('conversation.input.left', () => ctx.slots.register({
    name: 'conversation.input.left',
    id: SETTINGS_ID,
    order: 10, // After the resident chrome (access-mode chip, plan seat)
    locale: NS,
    inject: (sessionId: SessionId): ApprovalModeChipInjected => ({
      cachedMode: sessionModeCache.get(sessionId) ?? null,
      switchMode: async (mode: string) => {
        console.log('[approval-mode] Switching to mode:', mode)
        // Third parameter is the images array; slash commands carry no images.
        const result = await ctx.remote.commands.execute(sessionId, `/approval-mode ${mode}`, [])
        console.log('[approval-mode] Command result:', result)
        if (!result.ok) {
          console.error('[approval-mode] Command failed:', result.error)
          return `${result.error.message} (${result.error.code})`
        }
        if (result.value === undefined) {
          console.error('[approval-mode] No result value')
          return 'unknown command: /approval-mode'
        }
        // The remote call succeeded but the command handler rejected the mode.
        if (result.value.result.kind === 'error') {
          console.error('[approval-mode] Command handler error:', result.value.result.text)
          return result.value.result.text
        }
        // Update the local cache so a later revisit doesn't re-fetch.
        sessionModeCache.set(sessionId, mode as ApprovalMode)
        console.log('[approval-mode] Successfully switched to:', mode)
        return null
      },
      refreshMode: async () => {
        // The cache is only a first-paint hint; the server is the source of
        // truth. Always ask, so a mode changed outside this chip (slash
        // command, another window) cannot stay displayed after a revisit.
        const before = sessionModeCache.get(sessionId)
        const result = await ctx.remote.commands.execute(sessionId, '/approval-mode', [])
        if (!result.ok || result.value?.result.kind !== 'success') return null
        const mode = parseApprovalMode(result.value.result.text)
        if (mode === null) return null
        // A chip click completed while the query was in flight: its value is
        // newer than this answer, so leave the cache and the display alone.
        if (sessionModeCache.get(sessionId) !== before) return null
        sessionModeCache.set(sessionId, mode)
        if (mode !== before) console.log('[approval-mode] refreshed:', mode, '(was', before ?? 'none', ')')
        return mode
      },
    }),
  }, ApprovalModeChip))

  // ── Model directory (smart-classifier pickers) ──────────────────────────
  // The catalogue is a Host fact, not a settings value: adapters come and go
  // and a reconnect hands the page a different Host. The controller is created
  // once, invalidated by the two registry notifications, and dropped on a
  // connection reset; it loads lazily, so a page visit that never opens a
  // picker pays nothing.
  const directory = new SmartModelDirectoryController(ctx)
  ctx.effect(() => ctx.remote.$on('llm/adapters-updated', () => { directory.refresh() }), 'dsh-user-approval: adapter invalidations')
  ctx.effect(() => ctx.remote.$on('llm/models-updated', () => { directory.refresh() }), 'dsh-user-approval: model invalidations')
  // `connection/reset` is declared by the Client Connection package, which this
  // plugin does not depend on directly (the browser module table supplies it at
  // runtime). Cordis events are dynamic, so the listener below always fires;
  // the cast only widens the event-name type instead of adding a typing
  // dependency for one hook. A reconnect can mean a different Host, so the
  // cached catalogue — which names that Host's providers — has to go.
  const onConnectionReset = ctx.on as unknown as (name: 'connection/reset', listener: () => void) => () => void
  ctx.effect(() => onConnectionReset.call(ctx, 'connection/reset', () => { directory.reset() }), 'dsh-user-approval: connection generation')
  ctx.effect(() => () => { directory.dispose() }, 'dsh-user-approval: model directory')

  // ── Settings page (full-page editor for the ten user-editable fields) ────
  // The page lives at the bottom of the sidebar (`order: 1100`, after the
  // Plugins section). It binds the plugin entry's volatile Config via
  // `configForms.get`; user edits go through `form.set`/`form.unset` and are
  // persisted to the profile `cordis.patch.yml` user layer, where the Host
  // runtime folds them into the live volatile references.
  // The other 8 Config fields remain in the schema but are not editable here.
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: SETTINGS_ID,
    order: SETTINGS_ORDER,
    label: () => tPage('nav.label'),
    locale: NS_PAGE,
    inject: (): ApprovalModeSettingsInjected => ({
      // Bind the configuration form on the caller's plugin lifecycle — the
      // form's disposer is owned by this plugin's fiber. Binding adds no wire
      // read of its own because settings reads ride the shared describe mirror.
      form: ctx.configForms.get<Config>(ENTRY_ID),
      directory,
    }),
  }, ApprovalModeSettings))
}